import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static long[] factorialsArray;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));
        String[] inputLine = reader.readLine().split(" ");
        int totalN = Integer.parseInt(inputLine[0]);
        long totalK = Long.parseLong(inputLine[1]);
        factorialsArray = new long[totalN + 1];
        factorialsArray[0] = 1L;
        for (int i = 1; i <= totalN; i++) {
            factorialsArray[i] = (factorialsArray[i - 1] * i) % MOD;
        }
        if (totalK == 0) {
            writer.println(factorialsArray[totalN]);
        } else if (totalK >= totalN) {
            writer.println(0);
        } else {
            int kInt = (int) totalK;
            long sumTerms = 0L;
            long signFlag = 1L;
            int lVal = totalN - kInt;
            for (int i = 0; i <= lVal; i++) {
                long term = (quickPow(lVal - i, totalN) * choose(lVal, lVal - i)) % MOD;
                sumTerms = (sumTerms + signFlag * term + MOD) % MOD;
                signFlag *= -1L;
            }
            long answer = (2L * choose(totalN, kInt) * sumTerms) % MOD;
            writer.println(answer);
        }
        writer.close();
    }

    static long choose(int n, int r) {
        if (r == 0 || r == n) return 1L;
        if (r > n || r < 0) return 0L;
        long numerator = factorialsArray[n];
        long denominator = (factorialsArray[r] * factorialsArray[n - r]) % MOD;
        return (numerator * quickPow(denominator, MOD - 2)) % MOD;
    }

    static long quickPow(long base, long exp) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}
